proxy.main_template:
{{
	admin localhost:2019
	auto_https disable_redirects
	default_sni {hostname}
}}

(freedomnas_tls) {{
	tls {tls_dir}/cert.pem {tls_dir}/key.pem
}}

import {sites_dir}/*.caddy

proxy.redirect_template:
# freedomnas-names {domain}
http://*.{domain} {{
	redir https://{{host}}{{uri}} permanent
}}

*.{domain} {{
	{tls}
	respond "There is no site with this name on this NAS." 404
}}
